(()=>{'use strict';
 const style=document.createElement('link');style.rel='stylesheet';style.href='routine-sidebar.css?v=2';document.head.append(style);
 const days=[['ش',6,'شنبه'],['ی',0,'یکشنبه'],['د',1,'دوشنبه'],['س',2,'سه‌شنبه'],['چ',3,'چهارشنبه'],['پ',4,'پنجشنبه'],['ج',5,'جمعه']];
 const months=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
 const $=s=>document.querySelector(s),clean=v=>String(v||'').trim(),clock=v=>String(v||'').slice(0,5);
 const current=()=>typeof session!=='undefined'&&session?.user&&typeof mine==='function'&&mine()?session.user:null;
 const faNum=v=>String(v).replace(/\d/g,x=>'۰۱۲۳۴۵۶۷۸۹'[x]);
 const parts=d=>Object.fromEntries(new Intl.DateTimeFormat('en-US-u-ca-persian',{timeZone:'Asia/Tehran',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(d).filter(x=>x.type!=='literal').map(x=>[x.type,Number(x.value)]));
 const dateLabel=d=>{const p=parts(d);return `${faNum(p.day)} ${months[p.month-1]} ${faNum(p.year)}`};
 const previousMonth=d=>{const p=parts(d);let y=p.year,m=p.month-1;if(!m){m=12;y--}return `${months[m-1]} ${faNum(y)}`};
 const scheduleLabel=r=>r.schedule_type==='daily'?'هر روز':r.schedule_type==='monthly'?`هر ماه، روز ${fa(r.month_day)}`:`هفتگی · ${days.filter(([,v])=>(r.weekdays||[]).map(Number).includes(v)).map(([, ,n])=>n).join('، ')}`;
 const contextLabel=r=>({previous_day:'تاریخ روز قبل',previous_week:'هفتهٔ قبل',previous_month:'ماه قبل'})[r.date_context]||'بدون تاریخ در عنوان';
 function titlePreview(title,context){const d=new Date();if(!title)return 'عنوانِ کار اینجا پیش‌نمایش داده می‌شود.';if(context==='previous_day'){d.setDate(d.getDate()-1);return `${title} — ${dateLabel(d)}`}if(context==='previous_week'){d.setDate(d.getDate()-1);return `${title} — هفته منتهی به ${dateLabel(d)}`}if(context==='previous_month')return `${title} — ${previousMonth(d)}`;return title}
 async function list(){const user=current();if(!user)throw Error('برای تنظیم کار روتین وارد شوید.');const {data,error}=await db.from('sm_routine_alarms').select('*').eq('user_id',user.id).order('remind_at');if(error)throw error;return data||[]}
 function home(){return modalHead('کارهای روتین من')+'<section class="routine-reminders"><p class="routine-intro">یک قالب کار بسازید تا در روز و ساعت انتخابی، کار تازه وارد «کارهای من» شود. برای گزارش‌ها می‌توانید تاریخ یا بازهٔ مربوط را خودکار به عنوان اضافه کنید.</p><div class="routine-toolbar"><button class="primary" type="button" id="routineAdd">＋ کار روتین جدید</button><small>اعلان این دستگاه را از بخش «اعلان‌های این دستگاه» فعال کنید.</small></div><div id="routineList" class="routine-list" aria-live="polite"></div></section>'}
 function form(r={active:true,schedule_type:'weekly',weekdays:[6,0,1,2,3,4,5],remind_at:'08:00',date_context:'none'}){const picked=(r.weekdays||[]).map(Number),type=r.schedule_type||'weekly',context=r.date_context||'none';return `<section class="routine-editor"><button type="button" class="routine-back" id="routineBack">← بازگشت به کارهای روتین</button><h3>${r.id?'ویرایش کار روتین':'کار روتین جدید'}</h3><form id="routineForm"><label>عنوان کار<input name="title" maxlength="160" required placeholder="مثلاً گزارش روزانه" value="${esc(r.title||'')}"></label><label>شرح کار <small>(اختیاری)</small><textarea name="note" maxlength="800" rows="4" placeholder="شرحی که همراه هر کار جدید ثبت می‌شود">${esc(r.note||'')}</textarea></label><div class="routine-choice-grid"><label>تکرار کار<select name="schedule_type" id="routineSchedule"><option value="daily" ${type==='daily'?'selected':''}>هر روز</option><option value="weekly" ${type==='weekly'?'selected':''}>هفتگی</option><option value="monthly" ${type==='monthly'?'selected':''}>ماهانه</option></select></label><label>ساعت اعلان<input name="remind_at" type="time" required value="${clock(r.remind_at)||'08:00'}"></label></div><fieldset id="routineWeekdays"><legend>روزهای تکرار</legend><div class="routine-day-picker">${days.map(([s,v,n])=>`<label title="${n}"><input type="checkbox" name="weekdays" value="${v}" ${picked.includes(v)?'checked':''}><span>${s}</span></label>`).join('')}</div></fieldset><label id="routineMonthDay">روز ماه شمسی<input name="month_day" type="number" min="1" max="31" inputmode="numeric" value="${r.month_day||1}"></label><label>تاریخِ مربوط به کار<select name="date_context" id="routineContext"><option value="none" ${context==='none'?'selected':''}>بدون تاریخ در عنوان</option><option value="previous_day" ${context==='previous_day'?'selected':''}>روز قبل</option><option value="previous_week" ${context==='previous_week'?'selected':''}>هفتهٔ قبل</option><option value="previous_month" ${context==='previous_month'?'selected':''}>ماه قبل</option></select><small>برای گزارش‌ها، تاریخ یا بازهٔ مربوط به خود گزارش را به عنوان اضافه می‌کند.</small></label><div class="routine-preview"><span>پیش‌نمایش عنوان</span><b id="routinePreview"></b></div><label class="routine-active"><input name="active" type="checkbox" ${r.active!==false?'checked':''}><span>روتین فعال باشد</span></label><div class="routine-form-actions">${r.id?'<button class="danger" type="button" id="routineDelete">حذف روتین</button>':''}<button class="primary" type="submit">ذخیره روتین</button></div></form></section>`}
 async function renderList(){const box=$('#routineList');if(!box)return;box.innerHTML='<div class="routine-loading">در حال دریافت کارهای روتین…</div>';try{const rows=await list();box.innerHTML=rows.length?rows.map(r=>`<article class="routine-item ${r.active?'':'is-off'}"><button class="routine-toggle" type="button" data-toggle="${r.id}" aria-pressed="${r.active}">${r.active?'فعال':'خاموش'}</button><button class="routine-main" type="button" data-edit="${r.id}"><strong>${esc(r.title)}</strong>${r.note?`<small>${esc(r.note)}</small>`:''}<span>${clock(r.remind_at)} · ${scheduleLabel(r)} · ${contextLabel(r)}</span></button></article>`).join(''):'<div class="routine-empty"><b>هنوز کار روتینی ندارید.</b><span>برای کارهای تکراری، یک قالب بسازید تا در روز و ساعت دلخواه وارد فهرست کارهای شما شود.</span></div>';box.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.edit)));box.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{const r=rows.find(x=>x.id===b.dataset.toggle);b.disabled=true;const {error}=await db.from('sm_routine_alarms').update({active:!r.active,updated_at:new Date().toISOString()}).eq('id',r.id);if(error)message('تغییر ذخیره نشد.');await renderList()})}catch{box.innerHTML='<div class="routine-empty">دریافت کارهای روتین ممکن نشد. دوباره تلاش کنید.</div>'}}
 function edit(row={active:true,schedule_type:'weekly',weekdays:[6,0,1,2,3,4,5],remind_at:'08:00',date_context:'none'}){$('#sharedDetail').innerHTML=modalHead(row.id?'ویرایش کار روتین':'کار روتین جدید')+form(row);$('#sharedClose').onclick=()=>$('#sharedDialog').close();$('#routineBack').onclick=open;const f=$('#routineForm'),schedule=$('#routineSchedule'),weekdays=$('#routineWeekdays'),monthDay=$('#routineMonthDay'),context=$('#routineContext'),preview=$('#routinePreview');const sync=()=>{const type=schedule.value,showWeeks=type==='weekly',showMonth=type==='monthly';weekdays.hidden=!showWeeks;monthDay.hidden=!showMonth;weekdays.style.display=showWeeks?'':'none';monthDay.style.display=showMonth?'':'none';f.month_day.required=showMonth;preview.textContent=titlePreview(clean(f.title.value),context.value)};schedule.onchange=sync;f.title.oninput=sync;context.onchange=sync;sync();f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type="submit"]'),v=new FormData(f),type=v.get('schedule_type'),selected=[...f.querySelectorAll('[name="weekdays"]:checked')].map(x=>Number(x.value)),weekdays=type==='daily'?[0,1,2,3,4,5,6]:type==='monthly'?[0]:selected;if(type==='weekly'&&!weekdays.length)return message('حداقل یک روز را انتخاب کنید.');if(!project?.id)return message('ابتدا پروژه را انتخاب کنید.');button.disabled=true;const payload={user_id:current().id,project_id:project.id,title:clean(v.get('title')),note:clean(v.get('note')),remind_at:v.get('remind_at'),weekdays,schedule_type:type,month_day:type==='monthly'?Number(v.get('month_day')):null,date_context:v.get('date_context'),active:f.active.checked,updated_at:new Date().toISOString()};if(row.id)payload.id=row.id;const {error}=await db.from('sm_routine_alarms').upsert(payload);if(error){message('ذخیره روتین انجام نشد.');button.disabled=false;return}message('کار روتین ذخیره شد.');open()};const del=$('#routineDelete');if(del)del.onclick=async()=>{if(!confirm('این کار روتین حذف شود؟'))return;del.disabled=true;const {error}=await db.from('sm_routine_alarms').delete().eq('id',row.id);if(error){message('حذف انجام نشد.');del.disabled=false;return}message('روتین حذف شد.');open()}}
 function open(){if(!current())return message('اول وارد حساب خودتان شوید.');modal(home());$('#routineAdd').onclick=()=>edit();renderList()}
 function menu(){const add=$('#deskNewTask');if(!add||$('#routineSidebarButton'))return;const b=document.createElement('button');b.type='button';b.id='routineSidebarButton';b.className='routine-sidebar-button';b.innerHTML='<span aria-hidden="true">◷</span><b>کارهای روتین</b><i aria-hidden="true">+</i>';b.onclick=open;add.insertAdjacentElement('afterend',b)}
 new MutationObserver(menu).observe(document.body,{childList:true,subtree:true});menu();window.SamandisOpenRoutines=open;if(new URL(location.href).searchParams.get('routine'))setTimeout(open,600);const approvalStyle=document.createElement('link');approvalStyle.rel='stylesheet';approvalStyle.href='approval-inbox.css?v=1';document.head.append(approvalStyle);const approvalScript=document.createElement('script');approvalScript.src='approval-inbox.js?v=1';document.body.append(approvalScript);const dashboardScript=document.createElement('script');dashboardScript.src='dashboard-filters.js?v=1';document.body.append(dashboardScript);
})();
